CREATE TABLE settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), data jsonb NOT NULL);
INSERT INTO settings(data) VALUES ('{"paused":false,"aiEnabled":false,"aiBudget":10,"notificationChannel":"discord","notificationMinScore":60,"dailyLimit":5,"autoThreshold":85,"reminderDays":7}');
CREATE TABLE profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version integer UNIQUE NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO profiles(version,data) VALUES (1,'{}');
CREATE TABLE connectors (id text PRIMARY KEY, name text NOT NULL, kind text NOT NULL, enabled boolean NOT NULL DEFAULT false, authorized boolean NOT NULL DEFAULT false, auto_submit boolean NOT NULL DEFAULT false, failures integer NOT NULL DEFAULT 0, cursor jsonb NOT NULL DEFAULT '{}', config jsonb NOT NULL DEFAULT '{}', last_run_at timestamptz, last_error text, last_success_at timestamptz);
INSERT INTO connectors(id,name,kind,enabled,authorized) VALUES ('email','Boite email','email',false,true),('indeed','Indeed','import',true,true),('linkedin','LinkedIn','import',true,true),('meteojob','Meteojob','import',true,true),('hellowork','HelloWork','import',true,true),('wttj','Welcome to the Jungle','import',true,true),('manual','Import manuel','import',true,true);
CREATE TABLE source_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, external_id text NOT NULL, digest text NOT NULL, raw jsonb NOT NULL, collected_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source,external_id,digest));
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canonical_url text UNIQUE NOT NULL, data jsonb NOT NULL, state text NOT NULL DEFAULT 'new' CHECK(state IN ('new','seen','ignored','shortlisted')), fingerprint text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_fingerprint ON jobs(fingerprint);
CREATE TABLE job_sources (job_id uuid NOT NULL REFERENCES jobs(id), source_item_id uuid NOT NULL REFERENCES source_items(id), source text NOT NULL, external_id text NOT NULL, url text NOT NULL, PRIMARY KEY(job_id,source_item_id));
CREATE INDEX job_sources_identity ON job_sources(source,external_id);
CREATE TABLE duplicate_candidates (left_id uuid REFERENCES jobs(id), right_id uuid REFERENCES jobs(id), reason text NOT NULL, resolved boolean NOT NULL DEFAULT false, PRIMARY KEY(left_id,right_id), CHECK(left_id <> right_id));
CREATE TABLE evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), profile_id uuid NOT NULL REFERENCES profiles(id), cache_key text UNIQUE NOT NULL, score integer NOT NULL CHECK(score BETWEEN 0 AND 100), rejected boolean NOT NULL, data jsonb NOT NULL, ai jsonb, ai_status text NOT NULL DEFAULT 'disabled', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid UNIQUE NOT NULL REFERENCES jobs(id), status text NOT NULL DEFAULT 'to_apply' CHECK(status IN ('to_apply','applied','interview','rejected','withdrawn')), runner_state text NOT NULL DEFAULT 'needs_review' CHECK(runner_state IN ('queued','preparing','ready','submitting','confirmed','needs_review','failed','unknown')), connector_id text REFERENCES connectors(id), last_error text, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE application_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES applications(id), state text NOT NULL, mode text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE INDEX attempt_daily ON application_attempts(created_at) WHERE state IN ('submitting','confirmed','unknown');
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid REFERENCES jobs(id), profile_id uuid NOT NULL REFERENCES profiles(id), kind text NOT NULL CHECK(kind IN ('cv','letter')), content jsonb NOT NULL, path text NOT NULL, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reminders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid UNIQUE NOT NULL REFERENCES applications(id), due_at timestamptz NOT NULL, dismissed_at timestamptz, notified_at timestamptz);
CREATE TABLE events (id bigserial PRIMARY KEY, type text NOT NULL, entity_id text, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), logical_key text UNIQUE NOT NULL, channel text NOT NULL, data jsonb NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','sent','unknown','disabled','failed')), last_error text, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE ai_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cache_key text UNIQUE NOT NULL, reserved_eur numeric NOT NULL CHECK(reserved_eur >= 0), state text NOT NULL DEFAULT 'reserved', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE heartbeats (service text PRIMARY KEY, last_seen_at timestamptz NOT NULL DEFAULT now());
